export async function upload(req: Request): Promise<Response> {
  const form = await req.formData();
  const file = form.get('file') as File;
  const dest = join(UPLOAD_DIR, file.name);
  await Bun.write(dest, file);
  return Response.json({ url: `/files/${file.name}`, type: file.type });
}

export function download(req: Request, name: string): Response {
  return new Response(Bun.file(join(UPLOAD_DIR, name)));
}

