if (Number(req.headers.get('content-length') ?? Infinity) > MAX_UPLOAD_BYTES) return tooLarge(); // UP-2
const file = (await req.formData()).get('file');
if (!(file instanceof File) || file.size > MAX_UPLOAD_BYTES) return badRequest('file required');
const type = await sniffType(file); // UP-3: magic bytes, never the client's claim
if (!ALLOWED_TYPES.has(type)) return unsupported(type);
if ((await scanner.scan(file)).infected) return quarantine(file, req.user); // UP-4
const id = randomUUID(); // UP-1: server-chosen name, the client's name is metadata only
await storage.put(`uploads/${id}`, file, { contentType: type });
audit({ actor: req.user.id, action: 'file.upload', target: `file:${id}`, detail: { type, size: file.size } }); // UP-6
return Response.json({ id });

const grant = verifySignedUrl(req.url); // UP-5: HMAC-signed, 10 minute expiry, bound to the user
if (!grant || grant.userId !== req.user.id) return forbidden();
const obj = await storage.get(`uploads/${grant.fileId}`);
return new Response(obj.body, { headers: {
  'content-type': obj.contentType,
  'content-disposition': 'attachment', // UP-3: never rendered inline
  'x-content-type-options': 'nosniff',
} });
